impl Game{
 pub(crate) fn capture_native_retired_preamble(&self,index:usize)->Option<Capture>{let u=self.units.get(index)?;let slot=u.native_slot?;let m=self.native_group_rosters.members.get(slot)?.as_ref()?.clone();let layout=self.native_group_rosters.pool.get(usize::from(m.group));let role=if m.role==-1{Some(0)}else{usize::try_from(m.role).ok()};let valid_member=role.filter(|&r|r<21).is_some_and(|r|layout.and_then(|g|g.member(r))==Some(slot as u8));let p=&m.promotion;let paths=self.native_routes.borrow();let empty_paths=if paths.managed[slot]{paths.pool.links[slot].primary==0&&paths.pool.links[slot].secondary==0}else{!m.primary_path&&!m.secondary_path&&u.path.is_empty()&&u.native_route_pending.get().is_none()};let raw=Raw{position:[(u.x/2.).floor()as i16,(u.y/2.).floor()as i16],family:original_combat::animation_family(&u.kind),class:u.native_class7c,role:m.role,group:m.group,flags31:m.flags31,flags69:m.flags69,flags8a:m.flags8a,flags9c:u.native_flags9c,flags64:u.native_flags64,phase:u.native_phase35,frame:u.native_frame32,protection:u.native_protectionaa,order:u.native_order5c,reload:u.native_reload7b as u8,heading:original_combat::facing(u.angle),elevation:u.native_elevation76,cell:u.native_cell10,footprint:u.native_footprint18,permission:u.native_permission1c,pattern:u.native_pattern20.unwrap_or(0),step62:u.native_field62,word90:u.native_word90,control06:u.native_control06 as u8,flags71:u.native_initiative_scan.flags71,bonus8c:u.motion_bonus,speed8b:u.native_speed8b,pattern_rewritten:false,variant3c:u.native_timer3c as u8,timer3d:p.timer3d,frame40:p.frame40,timer41:p.timer41,delay7d:p.delay7d};Some(Capture{slot,upstream_generation:self.native_upstream_reactions.generation(slot)?,id:u.id,raw,member:m,context:self.native_group_rosters.current_roster,empty_paths,valid_member})}
 fn store_retired_callback_fields(&mut self,index:usize,r:Raw){let u=&mut self.units[index];u.native_phase35=r.phase;u.native_frame32=r.frame;u.native_protectionaa=r.protection;u.native_flags9c=r.flags9c;u.native_flags64=r.flags64;u.native_reload7b=r.reload as i8;u.native_cell10=r.cell;u.native_footprint18=r.footprint;u.native_permission1c=r.permission;u.native_field62=r.step62;u.native_word90=r.word90;if r.pattern_rewritten{u.native_pattern20=Some(r.pattern);u.native_speed8b=r.speed8b;}u.native_timer3c=r.variant3c as i8;}
 fn retired_callback_boundary(&mut self,index:usize,slot:usize,generation:u64,r:Raw,b:Boundary)->Outcome{self.update_native_upstream_retired_header(slot,generation,r);self.store_retired_callback_fields(index,r);self.native_route_boundary=Some(Runtime::RetiredUnitContinuation(slot,b));Outcome::Removed}
 pub(crate) fn finish_native_retired_preamble(&mut self,index:usize,capture:Option<Capture>)->Outcome{
  let Some(c)=capture else{return Outcome::Removed;};let mut r=c.raw;
  //The exact callback retains its old632194 even after4bba0 writes own5fFF.
  if self.units.get(index).is_none_or(|u|u.id!=c.id||u.native_slot.is_some())||self.units.iter().any(|u|u.native_slot==Some(c.slot)){self.native_route_boundary=Some(Runtime::RetiredUnitContinuation(c.slot,Boundary::SlotReuse));return Outcome::Removed;}
  if !c.valid_member||self.native_group_rosters.members[c.slot].is_some(){self.native_route_boundary=Some(Runtime::RetiredUnitContinuation(c.slot,Boundary::Membership));return Outcome::Removed;}
  //58ec0/58660/4bba0/52500 effects, already executed by the real adapter.
  r.flags31&=!(4|8|32);r.flags69&=!128;r.role=0;r.group=255;if r.family==4{r.family=255;}let pf=prefix(&mut r);self.store_retired_callback_fields(index,r);if pf.protected_seen{self.native_protected_order_seen=true;}if pf.clear_alias20&&!self.clear_native_retired_group_ff_aa(){return self.retired_callback_boundary(index,c.slot,c.upstream_generation,r,Boundary::AliasByte24);}
  self.update_native_upstream_retired_header(c.slot,c.upstream_generation,r);let prefix=r;let Some(context)=c.context.filter(|&g|g<240&&self.native_group_rosters.current_roster==Some(g))else{return self.retired_callback_boundary(index,c.slot,c.upstream_generation,r,Boundary::CurrentRoster);};if !c.empty_paths{return self.retired_callback_boundary(index,c.slot,c.upstream_generation,r,Boundary::Paths);}
  let terrain=if pf.frozen{0}else{let x=i32::from(r.position[0]);let y=i32::from(r.position[1]);let cell=((y*8+64)&0x7ff80)+((x+8)>>4);match self.dynamic_collision_terrain(cell as i16){Ok(t)=>t,Err(_)=>return self.retired_callback_boundary(index,c.slot,c.upstream_generation,r,Boundary::Terrain(255))}};
  let tick=self.motion_tick;if let Err(b)=finish(&mut r,terrain,|p|PATTERNS.iter().position(|&token|token==p).and_then(|i|crate::original_motion::known_pattern_step(i,tick)),||self.native_random()){return self.retired_callback_boundary(index,c.slot,c.upstream_generation,r,b);}

  let(camera,size)=self.native_view.unwrap_or(([0,0],[(self.map.width*16)as i16,(self.map.height*16)as i16]));let draw=if pf.frozen{None}else{picture(&mut r,camera,size)};self.store_retired_callback_fields(index,r);
  self.update_native_upstream_retired_header(c.slot,c.upstream_generation,r);
  //Only the proven subset augments the actual retired raw-UNIT owner. No
  //membership, activebit, actorposition, nativeSlot or selectableentity returns.
  if let Some(record)=self.native_workshop_units.continuations.get_mut(c.slot){let mut saved=crate::original_retired_workshop::Unit{position:r.position,flags31:r.flags31,role:r.role,group:r.group,flags69:r.flags69,flags9c:r.flags9c,primary:false,secondary:false,order:r.order,target_x:c.member.promotion.target_x,target_y:c.member.promotion.target_y,metadata:c.member.promotion.target_aux,icon:0,protection:r.protection,counter6e:self.units[index].native_counter6e,fieldb3:self.units[index].native_fieldb3 as u8};if let Some(old)=*record{saved.icon=old.icon;}*record=Some(saved);}
  if let Some(mut record)=draw{record.x=record.x.wrapping_add(camera[0]);record.y=record.y.wrapping_add(camera[1]);let row=crate::json!({"kind":"sprite","source":"retiredUnit","id":c.id,"nativeSlot":c.slot,"queueY":i32::from(record.y)*2,"palette":record.palette,"sprite":record.sprite,"x":i32::from(record.x)*2,"y":i32::from(record.y.wrapping_add(i16::from(record.offset)))*2,"scale":1.,"rotation":0.});if let Some(rows)=&mut self.native_display.units{rows.push((record,row));}}
  Outcome::Retired(Completion{slot:c.slot,context:0x60ec00+context as u32*72,prefix,unit:r,frozen:pf.frozen,picture:draw})
 }
}

